//refAssemblies: System.Net.Http.dll, Newtonsoft.Json.dll, TCAdmin.Web.Shared.dll, TCAdmin.Scripting.SDK.dll
using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using Newtonsoft.Json.Linq;
using TCAdmin.SDK.DynamicInput.Controls;
using TCAdmin.SDK.Models;
using TCAdmin.Web.Shared.Models;
using TCAdmin.Web.Shared.Models.DynamicInput;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Service variables that drive the game's Steam Branch / Branch Password config
// (SteamConfig.Branch = ${BranchSwitcher_SelectedBranch}, BranchPassword = ${BranchSwitcher_BranchPassword}).
const string SelectedBranchVar = "BranchSwitcher_SelectedBranch";
const string BranchPasswordVar = "BranchSwitcher_BranchPassword";

ScriptConsole.WriteLine("🎮  Steam Branch Switcher");
ScriptConsole.WriteLine("");

// Input/Alert dialogs only work when a person runs the script from the panel.
if (!IsInteractive)
{
    ScriptConsole.WriteLine("⚠️  Please run this from the panel — it needs to ask you which branch to use. Nothing was changed.");
    return;
}

var steam = ThisGame?.SteamConfig;
var appId = steam?.AppId ?? 0;
if (appId == 0)
{
    ScriptConsole.WriteLine("❌  This game has no Steam AppId configured, so there are no branches to switch between.");
    return;
}

// ===== Startup validation: self-provision the game variables + Steam-config wiring =====
// Idempotent — only writes when something is missing, so repeat runs are cheap.
var cfgCtx = GameServiceManager.TCAdminDbContext;
var gameId = ThisGame.BlueprintId;
var setupChanged = false;

if (!await cfgCtx.GameVariables.AnyAsync(v => v.GameId == gameId && v.Name == SelectedBranchVar))
{
    cfgCtx.GameVariables.Add(new GameVariable
    {
        GameId = gameId,
        BlueprintId = gameId,
        Name = SelectedBranchVar,
        DefaultValue = "public",
        Template = "${" + SelectedBranchVar + "}",
        CreatedDate = DateTime.UtcNow,
        Editor = new DynamicTextBox { Id = SelectedBranchVar, Label = "Branch" },
    });
    ScriptConsole.WriteLine($"🛠️  Created game variable '{SelectedBranchVar}'.");
    setupChanged = true;
}

if (!await cfgCtx.GameVariables.AnyAsync(v => v.GameId == gameId && v.Name == BranchPasswordVar))
{
    cfgCtx.GameVariables.Add(new GameVariable
    {
        GameId = gameId,
        BlueprintId = gameId,
        Name = BranchPasswordVar,
        DefaultValue = "",
        Template = "${" + BranchPasswordVar + "}",
        CreatedDate = DateTime.UtcNow,
        Editor = new DynamicTextBox { Id = BranchPasswordVar, Label = "Branch password", InputType = 1 },
    });
    ScriptConsole.WriteLine($"🛠️  Created game variable '{BranchPasswordVar}'.");
    setupChanged = true;
}

var wantBranch = "${" + SelectedBranchVar + "}";
var wantBranchPwd = "${" + BranchPasswordVar + "}";
if (!string.Equals(steam.Branch, wantBranch, StringComparison.Ordinal) ||
    !string.Equals(steam.BranchPassword, wantBranchPwd, StringComparison.Ordinal))
{
    steam.Branch = wantBranch;
    steam.BranchPassword = wantBranchPwd;
    cfgCtx.Entry(ThisGame).State = EntityState.Modified; // SteamConfig is a JSON column; force the write
    ScriptConsole.WriteLine("🛠️  Pointed the game's Steam Branch / Branch Password at the variables.");
    setupChanged = true;
}

if (setupChanged)
{
    await cfgCtx.SaveChangesAsync(ThisCancellationToken);
    ScriptConsole.WriteLine("✅  Branch Switcher setup verified.");
    ScriptConsole.WriteLine("");
}

// What the service is on now: its own saved value, otherwise the game's configured branch (or "public").
var currentBranch = ThisService.Variables != null && ThisService.Variables.ContainsKey(SelectedBranchVar)
    ? ThisService.Variables[SelectedBranchVar]?.ToString()
    : null;
if (string.IsNullOrWhiteSpace(currentBranch))
    currentBranch = string.IsNullOrWhiteSpace(steam.Branch) || steam.Branch.Contains("${") ? "public" : steam.Branch;

ScriptConsole.WriteLine($"🔍  Fetching available branches for '{ThisGame.Name}' (AppId {appId})...");

// Branch/beta data lives in Steam's PICS app-info; api.steamcmd.net mirrors it as JSON (no key/login).
JObject branches = null;
try
{
    using var http = new HttpClient();
    http.Timeout = TimeSpan.FromSeconds(25);
    http.DefaultRequestHeaders.UserAgent.ParseAdd("TCAdmin-BranchSwitcher/1.0");
    var json = await http.GetStringAsync($"https://api.steamcmd.net/v1/info/{appId}");
    var root = JObject.Parse(json);
    if (root["data"] is JObject data
        && data[appId.ToString()] is JObject app
        && app["depots"] is JObject depots
        && depots["branches"] is JObject found)
    {
        branches = found;
    }
}
catch (Exception ex)
{
    ScriptConsole.WriteLine("❌  Could not reach the Steam branch service: " + ex.Message);
    return;
}

if (branches == null || branches.Count == 0)
{
    ScriptConsole.WriteLine($"❌  No branch information was returned for AppId {appId}. The app may be invalid or publish no branch data.");
    return;
}

// Public branch first, then the rest alphabetically. Remember which branches need a password.
var ordered = branches.Properties()
    .OrderBy(p => string.Equals(p.Name, "public", StringComparison.OrdinalIgnoreCase) ? 0 : 1)
    .ThenBy(p => p.Name, StringComparer.OrdinalIgnoreCase)
    .ToList();

var passwordBranches = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
var combo = new DynamicComboBox
{
    Id = "SelectedBranch",
    Label = "Branch",
    Description = "Choose the branch this service should use for Steam updates.",
    Required = true,
    DefaultValue = currentBranch,
};

ScriptConsole.WriteLine($"✅  Found {ordered.Count} branch(es):");

foreach (var prop in ordered)
{
    var branch = prop.Value as JObject ?? new JObject();
    var name = prop.Name;
    var buildId = branch.Value<string>("buildid");
    if (string.IsNullOrEmpty(buildId)) buildId = "-";
    var passwordRequired = branch.Value<string>("pwdrequired") == "1";
    if (passwordRequired) passwordBranches.Add(name);

    var updated = "unknown";
    if (long.TryParse(branch.Value<string>("timeupdated"), out var ts))
        updated = DateTimeOffset.FromUnixTimeSeconds(ts).UtcDateTime.ToString("yyyy-MM-dd HH:mm") + " UTC";

    // Dropdown label (rich) + a matching console line.
    var itemText = $"{name}  —  build {buildId}, updated {updated}";
    if (passwordRequired) itemText += "  🔒";
    if (string.Equals(name, currentBranch, StringComparison.OrdinalIgnoreCase)) itemText += "  (current)";
    combo.Items.Add(new DynamicComboBoxItem { Text = itemText, Value = name });

    var parts = new List<string> { name, "build " + buildId, "updated " + updated };
    if (string.Equals(name, currentBranch, StringComparison.OrdinalIgnoreCase)) parts.Add("current");
    if (passwordRequired) parts.Add("🔒 password required");
    ScriptConsole.WriteLine("   • " + string.Join(" | ", parts));
}
ScriptConsole.WriteLine("");

// 1) Ask which branch to switch to.
var selectResult = await ThisScript.Input(new InputConfiguration { IsDialog = true, AllowCancel = true }, combo);
if (selectResult.Canceled)
{
    ScriptConsole.WriteLine("🚫  Cancelled — no changes were made.");
    return;
}

var selectedBranch = selectResult.Values != null && selectResult.Values.ContainsKey("SelectedBranch")
    ? selectResult.Values["SelectedBranch"]?.ToString()
    : null;
if (string.IsNullOrWhiteSpace(selectedBranch))
{
    ScriptConsole.WriteLine("🚫  No branch was selected — no changes were made.");
    return;
}

ScriptConsole.WriteLine($"👉  You selected the '{selectedBranch}' branch.");

// 2) If that branch is password-protected, ask for the branch password.
var branchPassword = "";
if (passwordBranches.Contains(selectedBranch))
{
    ScriptConsole.WriteLine("🔒  This branch is password-protected — please enter its Steam branch password.");
    var passwordBox = new DynamicTextBox
    {
        Id = "BranchPassword",
        Label = "Branch password",
        Description = $"The Steam beta password for the '{selectedBranch}' branch.",
        Required = true,
        InputType = 1, // MudBlazor InputType.Password → masked input
        MaxLength = 200,
    };

    var pwdResult = await ThisScript.Input(new InputConfiguration { IsDialog = true, AllowCancel = true }, passwordBox);
    if (pwdResult.Canceled)
    {
        ScriptConsole.WriteLine("🚫  Cancelled — no changes were made.");
        return;
    }
    branchPassword = pwdResult.Values != null && pwdResult.Values.ContainsKey("BranchPassword")
        ? pwdResult.Values["BranchPassword"]?.ToString() ?? ""
        : "";
    if (string.IsNullOrEmpty(branchPassword))
    {
        ScriptConsole.WriteLine("🚫  No password was entered — no changes were made.");
        return;
    }
}

// 3) Save the selection to this service's variables. Load the entity tracked in this scope, then force
// the row modified: Service.Variables is a JSON column with no EF ValueComparer, so neither an in-place
// edit nor a reassignment is picked up by DetectChanges — marking the entity Modified guarantees the write.
ScriptConsole.WriteLine("💾  Saving your selection to this service...");
var service = await GameServiceManager.GetAsync(ThisService.ServiceId);
if (service == null)
{
    ScriptConsole.WriteLine("❌  Could not load the service to save the selection.");
    return;
}

var updatedVars = new TCAdminVars();
if (service.Variables != null)
    foreach (var kv in service.Variables) updatedVars[kv.Key] = kv.Value;
updatedVars[SelectedBranchVar] = selectedBranch;
updatedVars[BranchPasswordVar] = branchPassword; // "" clears the password for non-protected branches
service.Variables = updatedVars;
GameServiceManager.TCAdminDbContext.Entry(service).State = EntityState.Modified;
await GameServiceManager.SaveChangesAsync(ThisCancellationToken);

ScriptConsole.WriteLine($"✅  Saved. This service is now set to the '{selectedBranch}' branch.");
ScriptConsole.WriteLine("");

// 4) Offer to run the Steam Update right now.
var runNow = await ThisScript.ShowMessageBox(
    "Run Steam Update now? 🚀",
    $"Switch this service to the '{selectedBranch}' branch now by running a Steam Update?\n\nThe server will be stopped while it downloads — this can take a while.",
    "Yes, run it now", "Not now");

if (runNow == true)
{
    ScriptConsole.WriteLine($"🚀  Starting Steam Update to the '{selectedBranch}' branch — please wait...");
    ScriptConsole.WriteLine("");

    var shownMilestones = new HashSet<int>();
    // Show downloaded files relative to the service root rather than as absolute paths
    // (e.g. "C:\TCAFiles\Users\luisa\104\bin\x.dll" -> "bin\x.dll").
    var updateRoot = (ThisService.RootDirectory ?? "").TrimEnd('\\', '/');
    var handlers = new ProgressHandlers
    {
        // Server-localized lines arrive as a [[TCA:[...]]]English envelope (normally resolved at the web
        // edge, but not on this direct ScriptConsole path) — strip the prefix; also relativize paths.
        OnMessage = (message, collapseKey) =>
        {
            if (!string.IsNullOrWhiteSpace(message))
            {
                if (message.StartsWith("[[TCA:") && message.Contains("]]]"))
                    message = message.Substring(message.IndexOf("]]]", StringComparison.Ordinal) + 3);
                if (updateRoot.Length > 0)
                    message = message.Replace(updateRoot + "\\", "", StringComparison.OrdinalIgnoreCase)
                                     .Replace(updateRoot + "/", "", StringComparison.OrdinalIgnoreCase);
                ScriptConsole.WriteLine(message);
            }
            return Task.CompletedTask;
        },
        OnDebugMessage = (message, collapseKey) =>
        {
            if (!string.IsNullOrWhiteSpace(message))
            {
                if (message.StartsWith("[[TCA:") && message.Contains("]]]"))
                    message = message.Substring(message.IndexOf("]]]", StringComparison.Ordinal) + 3);
                if (updateRoot.Length > 0)
                    message = message.Replace(updateRoot + "\\", "", StringComparison.OrdinalIgnoreCase)
                                     .Replace(updateRoot + "/", "", StringComparison.OrdinalIgnoreCase);
                ScriptConsole.WriteLine(message);
            }
            return Task.CompletedTask;
        },
        OnProgress = (percent) =>
        {
            var milestone = Math.Clamp(percent / 10 * 10, 0, 100); // report at 10% steps, once each
            if (shownMilestones.Add(milestone)) ScriptConsole.WriteLine($"   ⏳ {milestone}%");
            return Task.CompletedTask;
        },
    };

    try
    {
        // Pass null so the update runs Before/AfterSteamUpdate scripts in its OWN scripting environment
        // (avoids re-entering the one this interactive script is already using); all output still flows
        // to the console through the handlers above.
        var steamResult = await GameServiceManager.RunServiceSteamUpdate(
            ThisService.ServiceId, handlers, null, ThisCancellationToken);

        ScriptConsole.WriteLine("");
        if (steamResult != null && steamResult.Success)
            ScriptConsole.WriteLine($"✅  Steam Update finished — this service is now running the '{selectedBranch}' branch.");
        else
            ScriptConsole.WriteLine($"⚠️  Steam Update finished with a problem: {steamResult?.Message}");
    }
    catch (Exception ex)
    {
        ScriptConsole.WriteLine("❌  Steam Update failed: " + ex.Message);
    }
}
else
{
    ScriptConsole.WriteLine("➡️  Run a Steam Update on this service whenever you're ready to download the selected branch.");
    await ThisScript.Alert(
        "Branch updated ✅",
        $"This service is now set to the '{selectedBranch}' branch.\n\nRun a Steam Update when you're ready to download it and switch the server over.",
        "Got it");
}
